def secondBestWeight(n, edges):
    order = sorted(range(len(edges)), key=lambda i: edges[i][2])
    parent = list(range(n))
    members = [[i] for i in range(n)]
    mx = [[0] * n for _ in range(n)]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = 0
    in_tree = [False] * len(edges)
    for i in order:
        a, b, w = edges[i]
        ra, rb = find(a), find(b)
        if ra == rb:
            continue
        in_tree[i] = True
        total += w
        for x in members[ra]:
            row = mx[x]
            for y in members[rb]:
                row[y] = w
                mx[y][x] = w
        if len(members[ra]) < len(members[rb]):
            ra, rb = rb, ra
        members[ra].extend(members[rb])
        members[rb] = []
        parent[rb] = ra
    best = None
    for i, (a, b, w) in enumerate(edges):
        if not in_tree[i]:
            cand = total + w - mx[a][b]
            if best is None or cand < best:
                best = cand
    return -1 if best is None else best
